<?php require 'config/db.php';require 'includes/auth.php';require_login();$page_title='Threat Management';if($_SERVER['REQUEST_METHOD']==='POST'){require_role(['ADMIN','OPERATOR']);check_csrf();$action=$_POST['action']??'';if($action==='create'){$s=$pdo->prepare('INSERT INTO threats(threat_type,description,severity,status) VALUES(?,?,?,?)');$s->execute([trim($_POST['threat_type']),trim($_POST['description']),$_POST['severity'],$_POST['status']]);audit($pdo,'Threat created',$_POST['threat_type']);$_SESSION['flash']='Threat added.';}elseif($action==='status'){$s=$pdo->prepare('UPDATE threats SET status=? WHERE id=?');$s->execute([$_POST['status'],(int)$_POST['id']]);audit($pdo,'Threat status changed','Threat #'.(int)$_POST['id'].' to '.$_POST['status']);$_SESSION['flash']='Threat status updated.';}header('Location:threats.php');exit;}$rows=$pdo->query('SELECT * FROM threats ORDER BY id DESC')->fetchAll();require 'includes/header.php';?><section class="panel"><?php if(can_write()):?><h2>Add Threat</h2><form class="form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="create"><input name="threat_type" placeholder="Threat type" required><input name="description" placeholder="Description"><select name="severity"><option>Low</option><option>Medium</option><option>High</option><option>Critical</option></select><select name="status"><option>Monitoring</option><option>Active</option><option>Contained</option><option>Closed</option></select><button>Add Threat</button></form><?php endif;?><div class="tablewrap"><table><tr><th>Threat</th><th>Description</th><th>Severity</th><th>Status</th><th>Detected</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['threat_type'])?></td><td><?=e($r['description'])?></td><td><span class="badge <?=strtolower($r['severity'])?>"><?=e($r['severity'])?></span></td><td><?=e($r['status'])?></td><td><?=e($r['detected_at'])?></td><td><?php if(can_write()):?><form class="inline" method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><?php foreach(['Monitoring','Active','Contained','Closed'] as $x):?><option <?=$r['status']===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select><button class="smallbtn">Update</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></section><?php require 'includes/footer.php';?>
